use async_trait::async_trait;

/// A stored blob's location handle.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StoredBlob {
    pub storage_key: String,
    pub size_bytes: i64,
}

/// Writes, moves, and removes blobs. Keys are relative folder/file paths
/// generated by the implementation; every path segment passes the store's
/// own allowlist, so no user-controlled string becomes a path.
#[async_trait]
pub trait BlobStore: Send + Sync {
    /// Persists `bytes` at `{folder}/{stem}-{suffix}.{ext}` and returns the
    /// stored location handle.
    async fn put(
        &self,
        folder: &str,
        stem: &str,
        ext: &str,
        bytes: &[u8],
    ) -> Result<StoredBlob, String>;
    /// Removes the blob at `key`; an absent key is not an error.
    async fn delete(&self, key: &str) -> Result<(), String>;
    /// Reads the whole blob back. Bounded in practice by the upload caps.
    async fn read(&self, key: &str) -> Result<Vec<u8>, String>;
    /// Moves the blob to `{folder}/{stem}-{suffix}.{ext}` and returns the new
    /// key; used when a program folder goes away.
    async fn relocate(
        &self,
        key: &str,
        folder: &str,
        stem: &str,
        ext: &str,
    ) -> Result<String, String>;
    /// Removes a folder with everything under it; absent folders are fine.
    async fn delete_folder(&self, folder: &str) -> Result<(), String>;
}
